package com.servicerca.service;import com.servicerca.dto.rating.*;import com.servicerca.exception.*;import com.servicerca.model.*;import com.servicerca.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.util.UUID;@Service public class RatingService{private final ServiceRequestRepository requests;private final RatingRepository ratings;public RatingService(ServiceRequestRepository r,RatingRepository x){requests=r;ratings=x;}@Transactional public RatingResponse create(User author,UUID requestId,CreateRatingRequest body){var r=requests.findLocked(requestId).orElseThrow(()->new ResourceNotFoundException("Pedido inexistente."));if(r.getStatus()!=RequestStatus.COMPLETED)throw new BusinessException("WORK_NOT_COMPLETED","El trabajo aún no terminó.");if(r.getSelectedApplication()==null)throw new BusinessException("WORK_NOT_ASSIGNED","El trabajo no tiene profesional asignado.");var client=r.getClient().getId().equals(author.getId());var professional=r.getSelectedApplication().getProfessional().getId().equals(author.getId());if(!client&&!professional)throw new BusinessException("FORBIDDEN","No participás de este trabajo.");if(ratings.existsByRequestIdAndAuthorId(requestId,author.getId()))throw new BusinessException("ALREADY_RATED","Ya calificaste este trabajo.");var target=client?r.getSelectedApplication().getProfessional():r.getClient();var rating=ratings.save(Rating.builder().request(r).author(author).target(target).score(body.score()).comment(body.comment()).build());var total=target.getRating().multiply(BigDecimal.valueOf(target.getRatingCount())).add(BigDecimal.valueOf(body.score()));target.setRatingCount(target.getRatingCount()+1);target.setRating(total.divide(BigDecimal.valueOf(target.getRatingCount()),1,RoundingMode.HALF_UP));return new RatingResponse(rating.getId(),requestId,author.getId(),target.getId(),rating.getScore(),rating.getComment(),rating.getCreatedAt());}}
